#include <iostream>
#include <string>
using namespace std;
int main() {
    int T;
    cin >> T;
    while (T--) {
        string password;
        cin >> password;

        bool has_upper = false;
        bool has_digit = false;

        for (size_t i = 0; i < password.length(); ++i) {
            if (isupper(password[i])) {
                has_upper = true;
            }
            if (isdigit(password[i])) {
                has_digit = true;
            }
        }

        if (password.length() >= 8 && has_upper && has_digit) {
            cout << "Y\n";
        } else {
            cout << "N\n";
        }
    }
    return 0;
}

#include <iostream>
#include <cstring>
using namespace std;
int min_price[100005];
int main() {
    int M, N;
    cin >> M >> N;
    for (int i = 0; i <= M; i ++)
        min_price[i] = 1000000000;
    for (int i = 0; i < N; ++i) {
        int K, P;
        cin >> K >> P;
        min_price[K] = min(min_price[K], P);
    }
    int total_cost = 0;
    for (int k = 1; k <= M; ++k) {
        total_cost += min_price[k];
    }
    cout << total_cost;
    return 0;
}
